1	/**
2	 * @fileoverview Adapter management REST API routes
3	 *
4	 * This module provides Express routes for managing external adapter plugins:
5	 * - Listing all registered adapters (built-in + external)
6	 * - Installing external adapters from npm packages or local paths
7	 * - Unregistering external adapters
8	 *
9	 * Read-only routes require board org access. Mutating adapter management
10	 * routes require instance-admin access because they can install, reload, or
11	 * toggle server-side adapter code for the whole Paperclip instance.
12	 *
13	 * @module server/routes/adapters
14	 */
15	
16	import { execFile } from "node:child_process";
17	import fs from "node:fs";
18	import { readFile } from "node:fs/promises";
19	import path from "node:path";
20	import { promisify } from "node:util";
21	import { Router } from "express";
22	import {
23	  listServerAdapters,
24	  findServerAdapter,
25	  findActiveServerAdapter,
26	  listEnabledServerAdapters,
27	  registerServerAdapter,
28	  resolveExternalAdapterRegistration,
29	  unregisterServerAdapter,
30	  isOverridePaused,
31	  setOverridePaused,
32	} from "../adapters/registry.js";
33	import {
34	  listAdapterPlugins,
35	  addAdapterPlugin,
36	  removeAdapterPlugin,
37	  getAdapterPluginByType,
38	  getAdapterPluginsDir,
39	  getDisabledAdapterTypes,
40	  setAdapterDisabled,
41	} from "../services/adapter-plugin-store.js";
42	import type { AdapterPluginRecord } from "../services/adapter-plugin-store.js";
43	import type { ServerAdapterModule, AdapterConfigSchema } from "../adapters/types.js";
44	import { loadExternalAdapterPackage, getUiParserSource, getOrExtractUiParserSource, reloadExternalAdapter } from "../adapters/plugin-loader.js";
45	import { logger } from "../middleware/logger.js";
46	import { assertBoardOrgAccess, assertInstanceAdmin } from "./authz.js";
47	import { BUILTIN_ADAPTER_TYPES } from "../adapters/builtin-adapter-types.js";
48	
49	const execFileAsync = promisify(execFile);
50	
51	// ---------------------------------------------------------------------------
52	// Request / Response types
53	// ---------------------------------------------------------------------------
54	
55	interface AdapterInstallRequest {
56	  /** npm package name (e.g., "droid-paperclip-adapter") or local path */
57	  packageName: string;
58	  /** True if packageName is a local filesystem path */
59	  isLocalPath?: boolean;
60	  /** Target version for npm packages (optional, defaults to latest) */
61	  version?: string;
62	}
63	
64	interface AdapterCapabilities {
65	  supportsInstructionsBundle: boolean;
66	  supportsSkills: boolean;
67	  supportsLocalAgentJwt: boolean;
68	  requiresMaterializedRuntimeSkills: boolean;
69	}
70	
71	interface AdapterInfo {
72	  type: string;
73	  label: string;
74	  source: "builtin" | "external";
75	  modelsCount: number;
76	  loaded: boolean;
77	  disabled: boolean;
78	  capabilities: AdapterCapabilities;
79	  /** True when an external plugin has replaced a built-in adapter of the same type. */
80	  overriddenBuiltin?: boolean;
81	  /** True when the external override for a builtin type is currently paused. */
82	  overridePaused?: boolean;
83	  version?: string;
84	  packageName?: string;
85	  isLocalPath?: boolean;
86	}
87	
88	// ---------------------------------------------------------------------------
89	// Helpers
90	// ---------------------------------------------------------------------------
91	
92	/**
93	 * Resolve the adapter package directory (same rules as plugin-loader).
94	 */
95	function resolveAdapterPackageDir(record: AdapterPluginRecord): string {
96	  return record.localPath
97	    ? path.resolve(record.localPath)
98	    : path.resolve(getAdapterPluginsDir(), "node_modules", record.packageName);
99	}
100	
101	/**
102	 * Read `version` from the adapter's package.json on disk.
103	 * This is the source of truth for what is actually installed (npm or local path).
104	 *
105	 * TODO(cloudflare): readAdapterPackageVersionFromDisk uses fs.readFileSync to
106	 * read package.json from a locally installed npm package directory. The entire
107	 * concept of locally installed adapter packages assumes a persistent filesystem
108	 * and a Node-compatible module loader. For Workers compatibility the installed
109	 * version should be persisted to the database at install time and read from
110	 * there instead of from disk at request time.
111	 */
112	function readAdapterPackageVersionFromDisk(record: AdapterPluginRecord): string | undefined {
113	  try {
114	    const pkgDir = resolveAdapterPackageDir(record);
115	    const raw = fs.readFileSync(path.join(pkgDir, "package.json"), "utf-8");
116	    const v = JSON.parse(raw).version;
117	    return typeof v === "string" && v.trim().length > 0 ? v.trim() : undefined;
118	  } catch {
119	    return undefined;
120	  }
121	}
122	
123	function buildAdapterCapabilities(adapter: ServerAdapterModule): AdapterCapabilities {
124	  return {
125	    supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
126	    supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
127	    supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
128	    requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
129	  };
130	}
131	
132	function buildAdapterInfo(adapter: ServerAdapterModule, externalRecord: AdapterPluginRecord | undefined, disabledSet: Set<string>): AdapterInfo {
133	  const fromDisk = externalRecord ? readAdapterPackageVersionFromDisk(externalRecord) : undefined;
134	  return {
135	    type: adapter.type,
136	    label: adapter.type, // ServerAdapterModule doesn't have a separate "label" field; type serves as label
137	    source: externalRecord ? "external" : "builtin",
138	    modelsCount: (adapter.models ?? []).length,
139	    loaded: true, // If it's in the registry, it's loaded
140	    disabled: disabledSet.has(adapter.type),
141	    capabilities: buildAdapterCapabilities(adapter),
142	    overriddenBuiltin: externalRecord ? BUILTIN_ADAPTER_TYPES.has(adapter.type) : undefined,
143	    overridePaused: BUILTIN_ADAPTER_TYPES.has(adapter.type) ? isOverridePaused(adapter.type) : undefined,
144	    // Prefer on-disk package.json so the UI reflects bumps without relying on store-only fields.
145	    version: fromDisk ?? externalRecord?.version,
146	    packageName: externalRecord?.packageName,
147	    isLocalPath: externalRecord?.localPath ? true : undefined,
148	  };
149	}
150	
151	/**
152	 * Normalize a local path that may be a Windows path into a WSL-compatible path.
153	 *
154	 * - Windows paths (e.g., "C:\\Users\\...") are converted via `wslpath -u`.
155	 * - Paths already starting with `/mnt/` or `/` are returned as-is.
156	 */
157	async function normalizeLocalPath(rawPath: string): Promise<string> {
158	  // Already a POSIX path (WSL or native Linux)
159	  if (rawPath.startsWith("/")) {
160	    return rawPath;
161	  }
162	
163	  // Windows path detection: C:\ or C:/ pattern
164	  if (/^[A-Za-z]:[\\/]/.test(rawPath)) {
165	    try {
166	      const { stdout } = await execFileAsync("wslpath", ["-u", rawPath]);
167	      return stdout.trim();
168	    } catch (err) {
169	      logger.warn({ err, rawPath }, "wslpath conversion failed; using path as-is");
170	      return rawPath;
171	    }
172	  }
173	
174	  return rawPath;
175	}
176	
177	/**
178	 * Register an external adapter module into the server registry via the
179	 * hot-install path, resolving `sessionManagement` identically to how the
180	 * init-time IIFE does. Module-provided `sessionManagement` is honored first,
181	 * with fallback to the host registry by type for builtin-type overrides.
182	 *
183	 * Keeps the hot-install and init-time paths at parity so an adapter installed
184	 * via `POST /api/adapters/install` has the same shape in the registry as the
185	 * same adapter loaded on the next server restart.
186	 */
187	function registerWithSessionManagement(adapter: ServerAdapterModule): void {
188	  registerServerAdapter(resolveExternalAdapterRegistration(adapter));
189	}
190	
191	// ---------------------------------------------------------------------------
192	// Router
193	// ---------------------------------------------------------------------------
194	
195	export function adapterRoutes() {
196	  const router = Router();
197	
198	  /**
199	   * GET /api/adapters
200	   *
201	   * List all registered adapters (built-in + external).
202	   * Each entry includes whether the adapter is built-in or external,
203	   * its model count, and load status.
204	   */
205	  router.get("/adapters", async (_req, res) => {
206	    // Adapter inventory is needed by ordinary board members when creating or
207	    // editing company agents. Mutating adapter management routes below remain
208	    // instance-admin only because they affect the whole server runtime.
209	    assertBoardOrgAccess(_req);
210	
211	    const registeredAdapters = listServerAdapters();
212	    const externalRecords = new Map(
213	      listAdapterPlugins().map((r) => [r.type, r]),
214	    );
215	    const disabledSet = new Set(getDisabledAdapterTypes());
216	
217	    const result: AdapterInfo[] = registeredAdapters.map((adapter) =>
218	      buildAdapterInfo(adapter, externalRecords.get(adapter.type), disabledSet),
219	    ).sort((a, b) => a.type.localeCompare(b.type));
220	
221	    res.json(result);
222	  });
223	
224	  /**
225	   * POST /api/adapters/install
226	   *
227	   * Install an external adapter from an npm package or local path.
228	   *
229	   * Request body:
230	   * - packageName: string (required) — npm package name or local path
231	   * - isLocalPath?: boolean (default false)
232	   * - version?: string — target version for npm packages
233	   */
234	  router.post("/adapters/install", async (req, res) => {
235	    assertInstanceAdmin(req);
236	
237	    const { packageName, isLocalPath = false, version } = req.body as AdapterInstallRequest;
238	
239	    if (!packageName || typeof packageName !== "string") {
240	      res.status(400).json({ error: "packageName is required and must be a string." });
241	      return;
242	    }
243	
244	    // Strip version suffix if the UI sends "pkg@1.2.3" instead of separating it
245	    // e.g. "@henkey/hermes-paperclip-adapter@0.3.0" → packageName + version
246	    let canonicalName = packageName;
247	    let explicitVersion = version;
248	    const versionSuffix = packageName.match(/@(\d+\.\d+\.\d+.*)$/);
249	    if (versionSuffix) {
250	      // For scoped packages: "@scope/name@1.2.3" → "@scope/name" + "1.2.3"
251	      // For unscoped: "name@1.2.3" → "name" + "1.2.3"
252	      const lastAtIndex = packageName.lastIndexOf("@");
253	      if (lastAtIndex > 0 && !explicitVersion) {
254	        canonicalName = packageName.slice(0, lastAtIndex);
255	        explicitVersion = versionSuffix[1];
256	      }
257	    }
258	
259	    try {
260	      let installedVersion: string | undefined;
261	      let moduleLocalPath: string | undefined;
262	
263	      if (!isLocalPath) {
264	        // npm install into the managed directory
265	        const pluginsDir = getAdapterPluginsDir();
266	        const spec = explicitVersion ? `${canonicalName}@${explicitVersion}` : canonicalName;
267	
268	        logger.info({ spec, pluginsDir }, "Installing adapter package via npm");
269	
270	        await execFileAsync("npm", ["install", "--no-save", spec], {
271	          cwd: pluginsDir,
272	          timeout: 120_000,
273	        });
274	
275	        // Read installed version from package.json
276	        // TODO(cloudflare): reading package.json from the npm install directory
277	        // uses node:fs/promises at request time. For Workers compatibility the
278	        // installed version should be persisted to the DB by the install job and
279	        // read from there rather than from the local filesystem.
280	        try {
281	          const pkgJsonPath = path.join(pluginsDir, "node_modules", canonicalName, "package.json");
282	          const pkgContent = await import("node:fs/promises");
283	          const pkgRaw = await pkgContent.readFile(pkgJsonPath, "utf-8");
284	          const pkg = JSON.parse(pkgRaw);
285	          const v = pkg.version;
286	          installedVersion =
287	            typeof v === "string" && v.trim().length > 0 ? v.trim() : explicitVersion;
288	        } catch {
289	          installedVersion = explicitVersion;
290	        }
291	      } else {
292	        // Local path — normalize (e.g., Windows → WSL) and use the resolved path
293	        moduleLocalPath = path.resolve(await normalizeLocalPath(packageName));
294	        // TODO(cloudflare): reading package.json from a local-path adapter
295	        // directory uses node:fs/promises at request time. For Workers
296	        // compatibility the version should be captured during the install step
297	        // and stored in the database rather than read from disk at request time.
298	        try {
299	          const pkgRaw = await readFile(path.join(moduleLocalPath, "package.json"), "utf-8");
300	          const v = JSON.parse(pkgRaw).version;
301	          if (typeof v === "string" && v.trim().length > 0) {
302	            installedVersion = v.trim();
303	          }
304	        } catch {
305	          // leave installedVersion undefined if package.json is missing
306	        }
307	      }
308	
309	      // Load and register the adapter (use canonicalName for path resolution)
310	      const adapterModule = await loadExternalAdapterPackage(canonicalName, moduleLocalPath);
311	
312	      // Check if this type conflicts with a built-in adapter
313	      if (BUILTIN_ADAPTER_TYPES.has(adapterModule.type)) {
314	        res.status(409).json({
315	          error: `Adapter type "${adapterModule.type}" is a built-in adapter and cannot be overwritten.`,
316	        });
317	        return;
318	      }
319	
320	      // Check if already registered (indicates a reinstall/update)
321	      const existing = findServerAdapter(adapterModule.type);
322	      const isReinstall = existing !== null;
323	      if (existing) {
324	        unregisterServerAdapter(adapterModule.type);
325	        logger.info({ type: adapterModule.type }, "Unregistered existing adapter for replacement");
326	      }
327	
328	      // Register the new adapter
329	      registerWithSessionManagement(adapterModule);
330	
331	      // Persist the record (use canonicalName without version suffix)
332	      const record: AdapterPluginRecord = {
333	        packageName: canonicalName,
334	        localPath: moduleLocalPath,
335	        version: installedVersion ?? explicitVersion,
336	        type: adapterModule.type,
337	        installedAt: new Date().toISOString(),
338	      };
339	      addAdapterPlugin(record);
340	
341	      logger.info(
342	        { type: adapterModule.type, packageName: canonicalName },
343	        "External adapter installed and registered",
344	      );
345	
346	      res.status(201).json({
347	        type: adapterModule.type,
348	        packageName: canonicalName,
349	        version: installedVersion ?? explicitVersion,
350	        installedAt: record.installedAt,
351	        requiresRestart: isReinstall,
352	      });
353	    } catch (err) {
354	      const message = err instanceof Error ? err.message : String(err);
355	      logger.error({ err, packageName }, "Failed to install external adapter");
356	
357	      // Distinguish npm errors from load errors
358	      if (message.includes("npm") || message.includes("ERR!")) {
359	        res.status(500).json({ error: `npm install failed: ${message}` });
360	      } else {
361	        res.status(500).json({ error: `Failed to install adapter: ${message}` });
362	      }
363	    }
364	  });
365	
366	  /**
367	   * PATCH /api/adapters/:type
368	   *
369	   * Enable or disable an adapter. Disabled adapters are hidden from agent
370	   * creation menus but remain functional for existing agents.
371	   *
372	   * Request body: { "disabled": boolean }
373	   */
374	  router.patch("/adapters/:type", async (req, res) => {
375	    assertInstanceAdmin(req);
376	
377	    const adapterType = req.params.type;
378	    const { disabled } = req.body as { disabled?: boolean };
379	
380	    if (typeof disabled !== "boolean") {
381	      res.status(400).json({ error: "Request body must include { \"disabled\": true|false }." });
382	      return;
383	    }
384	
385	    // Check that the adapter exists in the registry
386	    const existing = findServerAdapter(adapterType);
387	    if (!existing) {
388	      res.status(404).json({ error: `Adapter "${adapterType}" is not registered.` });
389	      return;
390	    }
391	
392	    const changed = setAdapterDisabled(adapterType, disabled);
393	
394	    if (changed) {
395	      logger.info({ type: adapterType, disabled }, "Adapter enabled/disabled");
396	    }
397	
398	    res.json({ type: adapterType, disabled, changed });
399	  });
400	
401	  /**
402	   * PATCH /api/adapters/:type/override
403	   *
404	   * Pause or resume an external adapter's override of a builtin type.
405	   * When paused, the server returns the builtin adapter for all new requests
406	   * (execute, listModels, config schema, etc.).  Already-running sessions
407	   * keep the adapter they started with.
408	   */
409	  router.patch("/adapters/:type/override", async (req, res) => {
410	    assertInstanceAdmin(req);
411	
412	    const adapterType = req.params.type;
413	    const { paused } = req.body as { paused?: boolean };
414	
415	    if (typeof paused !== "boolean") {
416	      res.status(400).json({ error: "\"paused\" (boolean) is required in request body." });
417	      return;
418	    }
419	
420	    if (!BUILTIN_ADAPTER_TYPES.has(adapterType)) {
421	      res.status(400).json({ error: `Type "${adapterType}" is not a builtin adapter.` });
422	      return;
423	    }
424	
425	    const changed = setOverridePaused(adapterType, paused);
426	
427	    logger.info({ type: adapterType, paused, changed }, "Adapter override toggle");
428	
429	    res.json({ type: adapterType, paused, changed });
430	  });
431	
432	  /**
433	   * DELETE /api/adapters/:type
434	   *
435	   * Unregister an external adapter. Built-in adapters cannot be removed.
436	   */
437	  router.delete("/adapters/:type", async (req, res) => {
438	    assertInstanceAdmin(req);
439	
440	    const adapterType = req.params.type;
441	
442	    if (!adapterType) {
443	      res.status(400).json({ error: "Adapter type is required." });
444	      return;
445	    }
446	
447	    // Prevent removal of built-in adapters
448	    if (BUILTIN_ADAPTER_TYPES.has(adapterType)) {
449	      res.status(403).json({
450	        error: `Cannot remove built-in adapter "${adapterType}".`,
451	      });
452	      return;
453	    }
454	
455	    // Check that the adapter exists in the registry
456	    const existing = findServerAdapter(adapterType);
457	    if (!existing) {
458	      res.status(404).json({
459	        error: `Adapter "${adapterType}" is not registered.`,
460	      });
461	      return;
462	    }
463	
464	    // Check that it's an external adapter
465	    const externalRecord = getAdapterPluginByType(adapterType);
466	    if (!externalRecord) {
467	      res.status(404).json({
468	        error: `Adapter "${adapterType}" is not an externally installed adapter.`,
469	      });
470	      return;
471	    }
472	
473	    // If installed via npm (has packageName but no localPath), run npm uninstall
474	    if (externalRecord.packageName && !externalRecord.localPath) {
475	      try {
476	        const pluginsDir = getAdapterPluginsDir();
477	        await execFileAsync("npm", ["uninstall", externalRecord.packageName], {
478	          cwd: pluginsDir,
479	          timeout: 60_000,
480	        });
481	        logger.info(
482	          { type: adapterType, packageName: externalRecord.packageName },
483	          "npm uninstall completed for external adapter",
484	        );
485	      } catch (err) {
486	        logger.warn(
487	          { err, type: adapterType, packageName: externalRecord.packageName },
488	          "npm uninstall failed for external adapter; continuing with unregister",
489	        );
490	      }
491	    }
492	
493	    // Unregister from the runtime registry
494	    unregisterServerAdapter(adapterType);
495	
496	    // Remove from the persistent store
497	    removeAdapterPlugin(adapterType);
498	
499	    logger.info({ type: adapterType }, "External adapter unregistered and removed");
500	
501	    res.json({ type: adapterType, removed: true });
502	  });
503	
504	  /**
505	   * POST /api/adapters/:type/reload
506	   *
507	   * Reload an external adapter at runtime (for dev iteration without server restart).
508	   * Busts the ESM module cache, re-imports the adapter, and re-registers it.
509	   *
510	   * Cannot be used on built-in adapter types.
511	   */
512	  router.post("/adapters/:type/reload", async (req, res) => {
513	    assertInstanceAdmin(req);
514	
515	    const type = req.params.type;
516	
517	    // Built-in adapters cannot be reloaded unless overridden by an external one
518	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
519	      res.status(400).json({ error: "Cannot reload built-in adapter." });
520	      return;
521	    }
522	
523	    // Reload the adapter module (busts ESM cache, re-imports)
524	    try {
525	      const newModule = await reloadExternalAdapter(type);
526	
527	      // Not found in the external adapter store
528	      if (!newModule) {
529	        res.status(404).json({ error: `Adapter "${type}" is not an externally installed adapter.` });
530	        return;
531	      }
532	
533	      // Swap in the reloaded module
534	      unregisterServerAdapter(type);
535	      registerWithSessionManagement(newModule);
536	      configSchemaCache.delete(type);
537	
538	      // Sync store.version from package.json (store may be missing version for local installs).
539	      const record = getAdapterPluginByType(type);
540	      let newVersion: string | undefined;
541	      if (record) {
542	        newVersion = readAdapterPackageVersionFromDisk(record);
543	        if (newVersion) {
544	          addAdapterPlugin({ ...record, version: newVersion });
545	        }
546	      }
547	
548	      logger.info({ type, version: newVersion }, "External adapter reloaded at runtime");
549	
550	      res.json({ type, version: newVersion, reloaded: true });
551	    } catch (err) {
552	      const message = err instanceof Error ? err.message : String(err);
553	      logger.error({ err, type }, "Failed to reload external adapter");
554	      res.status(500).json({ error: `Failed to reload adapter: ${message}` });
555	    }
556	  });
557	
558	  // ── POST /api/adapters/:type/reinstall ──────────────────────────────────
559	  // Reinstall an npm-sourced external adapter (pulls latest from registry).
560	  // Local-path adapters cannot be reinstalled — use Reload instead.
561	  //
562	  // This is a convenience shortcut for remove + install with the same
563	  // package name, but without the risk of losing the store record.
564	  router.post("/adapters/:type/reinstall", async (req, res) => {
565	    assertInstanceAdmin(req);
566	
567	    const type = req.params.type;
568	
569	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
570	      res.status(400).json({ error: "Cannot reinstall built-in adapter." });
571	      return;
572	    }
573	
574	    const record = getAdapterPluginByType(type);
575	    if (!record) {
576	      res.status(404).json({ error: `Adapter "${type}" is not an externally installed adapter.` });
577	      return;
578	    }
579	
580	    if (record.localPath) {
581	      res.status(400).json({ error: "Local-path adapters cannot be reinstalled. Use Reload instead." });
582	      return;
583	    }
584	
585	    try {
586	      const pluginsDir = getAdapterPluginsDir();
587	
588	      logger.info({ type, packageName: record.packageName }, "Reinstalling adapter package via npm");
589	
590	      await execFileAsync("npm", ["install", "--no-save", record.packageName], {
591	        cwd: pluginsDir,
592	        timeout: 120_000,
593	      });
594	
595	      // Reload the freshly installed adapter
596	      const newModule = await reloadExternalAdapter(type);
597	      if (!newModule) {
598	        res.status(500).json({ error: "npm install succeeded but adapter reload failed." });
599	        return;
600	      }
601	
602	      unregisterServerAdapter(type);
603	      registerWithSessionManagement(newModule);
604	      configSchemaCache.delete(type);
605	
606	      // Sync store version from disk
607	      let newVersion: string | undefined;
608	      const updatedRecord = getAdapterPluginByType(type);
609	      if (updatedRecord) {
610	        newVersion = readAdapterPackageVersionFromDisk(updatedRecord);
611	        if (newVersion) {
612	          addAdapterPlugin({ ...updatedRecord, version: newVersion });
613	        }
614	      }
615	
616	      logger.info({ type, version: newVersion }, "Adapter reinstalled from npm");
617	
618	      res.json({ type, version: newVersion, reinstalled: true });
619	    } catch (err) {
620	      const message = err instanceof Error ? err.message : String(err);
621	      logger.error({ err, type }, "Failed to reinstall adapter");
622	      res.status(500).json({ error: `Reinstall failed: ${message}` });
623	    }
624	  });
625	
626	  // ── GET /api/adapters/:type/config-schema ────────────────────────────────
627	  // Serve a declarative config schema for an adapter's UI form fields.
628	  // The adapter's getConfigSchema() resolves all options (static and dynamic)
629	  // so the UI receives a fully hydrated schema in a single fetch.
630	  const configSchemaCache = new Map<string, {
631	    adapter: ServerAdapterModule;
632	    schema: AdapterConfigSchema;
633	    fetchedAt: number;
634	  }>();
635	  const CONFIG_SCHEMA_TTL_MS = 30_000;
636	
637	  router.get("/adapters/:type/config-schema", async (req, res) => {
638	    // Config schemas are read-only form metadata used when org members create
639	    // or edit agents; they do not install or execute new adapter code.
640	    assertBoardOrgAccess(req);
641	    const { type } = req.params;
642	
643	    const adapter = findActiveServerAdapter(type);
644	    if (!adapter) {
645	      res.status(404).json({ error: `Adapter "${type}" is not registered.` });
646	      return;
647	    }
648	    if (!adapter.getConfigSchema) {
649	      res.status(404).json({ error: `Adapter "${type}" does not provide a config schema.` });
650	      return;
651	    }
652	
653	    const cached = configSchemaCache.get(type);
654	    if (cached && cached.adapter === adapter && Date.now() - cached.fetchedAt < CONFIG_SCHEMA_TTL_MS) {
655	      res.json(cached.schema);
656	      return;
657	    }
658	
659	    try {
660	      const schema = await adapter.getConfigSchema();
661	      configSchemaCache.set(type, { adapter, schema, fetchedAt: Date.now() });
662	      res.json(schema);
663	    } catch (err) {
664	      const message = err instanceof Error ? err.message : String(err);
665	      logger.error({ err, type }, "Failed to resolve config schema");
666	      res.status(500).json({ error: `Failed to resolve config schema: ${message}` });
667	    }
668	  });
669	
670	  // ── GET /api/adapters/:type/ui-parser.js ─────────────────────────────────
671	  // Serve the self-contained UI parser JS for an adapter type.
672	  // This allows external adapters to provide custom run-log parsing
673	  // without modifying Paperclip's source code.
674	  //
675	  // The adapter package must export a "./ui-parser" entry in package.json
676	  // pointing to a self-contained ESM module with zero runtime dependencies.
677	  router.get("/adapters/:type/ui-parser.js", (req, res) => {
678	    // UI parsers are read-only assets for displaying existing run output.
679	    // Runtime-changing adapter management routes above require instance admin.
680	    assertBoardOrgAccess(req);
681	    const { type } = req.params;
682	    const source = getOrExtractUiParserSource(type);
683	    if (!source) {
684	      res.status(404).json({ error: `No UI parser available for adapter "${type}".` });
685	      return;
686	    }
687	    res.type("application/javascript").send(source);
688	  });
689	
690	  return router;
691	}
